@@ -213,3 +213,3 @@
 FROM raw_orders
-WHERE try_cast(departure_date AS DATE) < cast(try_cast(order_created_at AS TIMESTAMPTZ) AS DATE);
+WHERE try_cast(departure_date AS DATE) < try_cast(substr(order_created_at, 1, 10) AS DATE);

